package main

// MinStack implements a stack that supports push, pop, top, and getMin
// all in O(1) time complexity. It uses an auxiliary stack to track the
// current minimum at each level of the main stack.
type MinStack struct {
	stack    []int
	minStack []int
}

// NewMinStack creates and returns a new empty MinStack.
func NewMinStack() *MinStack {
	return &MinStack{
		stack:    make([]int, 0),
		minStack: make([]int, 0),
	}
}

// Push adds an element to the top of the stack.
func (ms *MinStack) Push(val int) {
	ms.stack = append(ms.stack, val)
	if len(ms.minStack) == 0 || val <= ms.minStack[len(ms.minStack)-1] {
		ms.minStack = append(ms.minStack, val)
	}
}

// Pop removes the element from the top of the stack.
// Returns the removed element and true, or 0 and false if the stack is empty.
func (ms *MinStack) Pop() (int, bool) {
	if len(ms.stack) == 0 {
		return 0, false
	}
	val := ms.stack[len(ms.stack)-1]
	ms.stack = ms.stack[:len(ms.stack)-1]
	if val == ms.minStack[len(ms.minStack)-1] {
		ms.minStack = ms.minStack[:len(ms.minStack)-1]
	}
	return val, true
}

// Top returns the element at the top of the stack without removing it.
// Returns the top element and true, or 0 and false if the stack is empty.
func (ms *MinStack) Top() (int, bool) {
	if len(ms.stack) == 0 {
		return 0, false
	}
	return ms.stack[len(ms.stack)-1], true
}

// GetMin returns the minimum element currently in the stack.
// Returns the minimum and true, or 0 and false if the stack is empty.
func (ms *MinStack) GetMin() (int, bool) {
	if len(ms.minStack) == 0 {
		return 0, false
	}
	return ms.minStack[len(ms.minStack)-1], true
}

// IsEmpty returns true if the stack contains no elements.
func (ms *MinStack) IsEmpty() bool {
	return len(ms.stack) == 0
}

// Size returns the number of elements in the stack.
func (ms *MinStack) Size() int {
	return len(ms.stack)
}

package main

import (
	"testing"
)

func TestNewMinStack(t *testing.T) {
	ms := NewMinStack()
	if !ms.IsEmpty() {
		t.Error("New MinStack should be empty")
	}
	if ms.Size() != 0 {
		t.Errorf("New MinStack size should be 0, got %d", ms.Size())
	}
}

func TestPushAndTop(t *testing.T) {
	ms := NewMinStack()
	ms.Push(5)
	top, ok := ms.Top()
	if !ok || top != 5 {
		t.Errorf("Top should be 5, got %d (ok=%v)", top, ok)
	}
	ms.Push(3)
	top, ok = ms.Top()
	if !ok || top != 3 {
		t.Errorf("Top should be 3, got %d (ok=%v)", top, ok)
	}
	ms.Push(7)
	top, ok = ms.Top()
	if !ok || top != 7 {
		t.Errorf("Top should be 7, got %d (ok=%v)", top, ok)
	}
}

func TestPushAndPop(t *testing.T) {
	ms := NewMinStack()
	ms.Push(1)
	ms.Push(2)
	ms.Push(3)

	val, ok := ms.Pop()
	if !ok || val != 3 {
		t.Errorf("Pop should return 3, got %d (ok=%v)", val, ok)
	}
	val, ok = ms.Pop()
	if !ok || val != 2 {
		t.Errorf("Pop should return 2, got %d (ok=%v)", val, ok)
	}
	val, ok = ms.Pop()
	if !ok || val != 1 {
		t.Errorf("Pop should return 1, got %d (ok=%v)", val, ok)
	}
	if !ms.IsEmpty() {
		t.Error("Stack should be empty after popping all elements")
	}
}

func TestGetMin(t *testing.T) {
	ms := NewMinStack()
	ms.Push(5)
	min, ok := ms.GetMin()
	if !ok || min != 5 {
		t.Errorf("GetMin should be 5, got %d (ok=%v)", min, ok)
	}

	ms.Push(3)
	min, ok = ms.GetMin()
	if !ok || min != 3 {
		t.Errorf("GetMin should be 3, got %d (ok=%v)", min, ok)
	}

	ms.Push(7)
	min, ok = ms.GetMin()
	if !ok || min != 3 {
		t.Errorf("GetMin should still be 3, got %d (ok=%v)", min, ok)
	}

	ms.Push(1)
	min, ok = ms.GetMin()
	if !ok || min != 1 {
		t.Errorf("GetMin should be 1, got %d (ok=%v)", min, ok)
	}
}

func TestGetMinAfterPop(t *testing.T) {
	ms := NewMinStack()
	ms.Push(5)
	ms.Push(3)
	ms.Push(7)
	ms.Push(1)

	min, _ := ms.GetMin()
	if min != 1 {
		t.Errorf("GetMin should be 1, got %d", min)
	}

	ms.Pop() // remove 1
	min, _ = ms.GetMin()
	if min != 3 {
		t.Errorf("GetMin should be 3 after popping 1, got %d", min)
	}

	ms.Pop() // remove 7
	min, _ = ms.GetMin()
	if min != 3 {
		t.Errorf("GetMin should still be 3, got %d", min)
	}

	ms.Pop() // remove 3
	min, _ = ms.GetMin()
	if min != 5 {
		t.Errorf("GetMin should be 5 after popping 3, got %d", min)
	}
}

func TestDuplicateMinValues(t *testing.T) {
	ms := NewMinStack()
	ms.Push(2)
	ms.Push(2)
	ms.Push(2)

	min, ok := ms.GetMin()
	if !ok || min != 2 {
		t.Errorf("GetMin should be 2, got %d (ok=%v)", min, ok)
	}

	ms.Pop()
	min, _ = ms.GetMin()
	if min != 2 {
		t.Errorf("GetMin should still be 2, got %d", min)
	}

	ms.Pop()
	min, _ = ms.GetMin()
	if min != 2 {
		t.Errorf("GetMin should still be 2, got %d", min)
	}

	ms.Pop()
	_, ok = ms.GetMin()
	if ok {
		t.Error("GetMin should return false on empty stack")
	}
}

func TestNegativeValues(t *testing.T) {
	ms := NewMinStack()
	ms.Push(-5)
	ms.Push(-3)
	ms.Push(-10)

	min, ok := ms.GetMin()
	if !ok || min != -10 {
		t.Errorf("GetMin should be -10, got %d (ok=%v)", min, ok)
	}

	ms.Pop() // remove -10
	min, _ = ms.GetMin()
	if min != -5 {
		t.Errorf("GetMin should be -5, got %d", min)
	}
}

func TestMixedPositiveNegative(t *testing.T) {
	ms := NewMinStack()
	ms.Push(-1)
	ms.Push(10)
	ms.Push(-5)
	ms.Push(3)

	min, _ := ms.GetMin()
	if min != -5 {
		t.Errorf("GetMin should be -5, got %d", min)
	}

	ms.Pop() // remove 3
	ms.Pop() // remove -5
	min, _ = ms.GetMin()
	if min != -1 {
		t.Errorf("GetMin should be -1, got %d", min)
	}
}

func TestEmptyStackOperations(t *testing.T) {
	ms := NewMinStack()

	_, ok := ms.Pop()
	if ok {
		t.Error("Pop on empty stack should return false")
	}

	_, ok = ms.Top()
	if ok {
		t.Error("Top on empty stack should return false")
	}

	_, ok = ms.GetMin()
	if ok {
		t.Error("GetMin on empty stack should return false")
	}
}

func TestSingleElement(t *testing.T) {
	ms := NewMinStack()
	ms.Push(42)

	top, ok := ms.Top()
	if !ok || top != 42 {
		t.Errorf("Top should be 42, got %d (ok=%v)", top, ok)
	}

	min, ok := ms.GetMin()
	if !ok || min != 42 {
		t.Errorf("GetMin should be 42, got %d (ok=%v)", min, ok)
	}

	val, ok := ms.Pop()
	if !ok || val != 42 {
		t.Errorf("Pop should return 42, got %d (ok=%v)", val, ok)
	}

	if !ms.IsEmpty() {
		t.Error("Stack should be empty after popping single element")
	}
}

func TestLargeSequence(t *testing.T) {
	ms := NewMinStack()
	// Push 1000 elements in descending order: 999, 998, ..., 0
	for i := 999; i >= 0; i-- {
		ms.Push(i)
	}

	if ms.Size() != 1000 {
		t.Errorf("Size should be 1000, got %d", ms.Size())
	}

	min, ok := ms.GetMin()
	if !ok || min != 0 {
		t.Errorf("GetMin should be 0, got %d (ok=%v)", min, ok)
	}

	top, ok := ms.Top()
	if !ok || top != 0 {
		t.Errorf("Top should be 0, got %d (ok=%v)", top, ok)
	}

	// Pop all and verify descending order
	for i := 0; i < 1000; i++ {
		val, ok := ms.Pop()
		if !ok || val != i {
			t.Errorf("Pop #%d should return %d, got %d (ok=%v)", i, i, val, ok)
		}
	}

	if !ms.IsEmpty() {
		t.Error("Stack should be empty after popping all elements")
	}
}

func TestSizeAndIsEmpty(t *testing.T) {
	ms := NewMinStack()
	if ms.Size() != 0 {
		t.Errorf("Size should be 0, got %d", ms.Size())
	}
	if !ms.IsEmpty() {
		t.Error("IsEmpty should be true")
	}

	ms.Push(1)
	if ms.Size() != 1 {
		t.Errorf("Size should be 1, got %d", ms.Size())
	}
	if ms.IsEmpty() {
		t.Error("IsEmpty should be false")
	}

	ms.Push(2)
	if ms.Size() != 2 {
		t.Errorf("Size should be 2, got %d", ms.Size())
	}

	ms.Pop()
	if ms.Size() != 1 {
		t.Errorf("Size should be 1, got %d", ms.Size())
	}
}

func TestZeroValues(t *testing.T) {
	ms := NewMinStack()
	ms.Push(0)
	ms.Push(5)
	ms.Push(0)

	min, ok := ms.GetMin()
	if !ok || min != 0 {
		t.Errorf("GetMin should be 0, got %d (ok=%v)", min, ok)
	}

	ms.Pop() // remove 0
	min, _ = ms.GetMin()
	if min != 0 {
		t.Errorf("GetMin should still be 0, got %d", min)
	}

	ms.Pop() // remove 5
	min, _ = ms.GetMin()
	if min != 0 {
		t.Errorf("GetMin should be 0, got %d", min)
	}
}

func TestInterleavedOperations(t *testing.T) {
	ms := NewMinStack()

	ms.Push(10)
	ms.Push(5)
	min, _ := ms.GetMin()
	if min != 5 {
		t.Errorf("GetMin should be 5, got %d", min)
	}

	ms.Pop()
	min, _ = ms.GetMin()
	if min != 10 {
		t.Errorf("GetMin should be 10, got %d", min)
	}

	ms.Push(3)
	ms.Push(8)
	ms.Push(1)
	min, _ = ms.GetMin()
	if min != 1 {
		t.Errorf("GetMin should be 1, got %d", min)
	}

	ms.Pop()
	ms.Pop()
	min, _ = ms.GetMin()
	if min != 3 {
		t.Errorf("GetMin should be 3, got %d", min)
	}
}
